#!/usr/bin/env python3
"""Classify a lesson into likely project improvement destinations."""

from __future__ import annotations

import argparse
import json
from pathlib import Path


RULE_KEYWORDS = ("rule", "instruction", "agent", "claude", "codex", "agents.md", "claude.md", "convention")
TEST_KEYWORDS = ("bug", "regression", "expected", "actual", "schema", "frontmatter", "fixture", "unit", "e2e")
CI_KEYWORDS = ("ci", "workflow", "github actions", "check", "pull request", "runner", "minutes")
SCRIPT_KEYWORDS = ("manual", "repeat", "preflight", "validate", "script", "command")
DOC_KEYWORDS = ("setup", "runbook", "readme", "documentation", "how to", "deploy")
ADR_KEYWORDS = ("architecture", "decision", "tradeoff", "why", "adr")


def score(text: str, keywords: tuple[str, ...]) -> int:
    lower = text.lower()
    return sum(1 for keyword in keywords if keyword in lower)


def classify(text: str) -> list[dict[str, object]]:
    candidates = [
        ("agent_instructions", score(text, RULE_KEYWORDS), "Put reusable project rules in shared agent instructions."),
        ("test", score(text, TEST_KEYWORDS), "Add a regression or validation test when behavior is machine-checkable."),
        ("ci", score(text, CI_KEYWORDS), "Wire existing checks into CI when review needs automatic protection."),
        ("script", score(text, SCRIPT_KEYWORDS), "Create a deterministic command for repeated manual validation."),
        ("docs", score(text, DOC_KEYWORDS), "Document setup or process knowledge for future contributors."),
        ("adr", score(text, ADR_KEYWORDS), "Record durable architecture decisions and tradeoffs."),
    ]
    ranked = [
        {"destination": name, "score": value, "reason": reason}
        for name, value, reason in sorted(candidates, key=lambda item: item[1], reverse=True)
        if value > 0
    ]
    if not ranked:
        ranked.append(
            {
                "destination": "no_automation_yet",
                "score": 0,
                "reason": "No strong signal found. Treat as a one-off unless recurrence or risk is clear.",
            }
        )
    return ranked


def main() -> None:
    parser = argparse.ArgumentParser()
    parser.add_argument("--text", help="Lesson text to classify.")
    parser.add_argument("--file", help="File containing lesson text.")
    parser.add_argument("--output", help="Optional JSON output path.")
    args = parser.parse_args()

    if args.file:
        text = Path(args.file).read_text(encoding="utf-8", errors="replace")
    elif args.text:
        text = args.text
    else:
        parser.error("Provide --text or --file")

    result = {"input_excerpt": text[:500], "ranked_destinations": classify(text)}
    payload = json.dumps(result, indent=2, sort_keys=True)
    if args.output:
        Path(args.output).write_text(payload + "\n", encoding="utf-8")
    else:
        print(payload)


if __name__ == "__main__":
    main()

#!/usr/bin/env python3
"""Inspect a repository's visible CI and local verification surface."""

from __future__ import annotations

import argparse
import json
import re
from pathlib import Path
from typing import Any


def read_text(path: Path, limit: int = 40000) -> str:
    try:
        return path.read_text(encoding="utf-8", errors="replace")[:limit]
    except OSError:
        return ""


def load_package(root: Path) -> dict[str, Any]:
    path = root / "package.json"
    if not path.exists():
        return {}
    try:
        return json.loads(read_text(path))
    except json.JSONDecodeError:
        return {"_parse_error": True}


def workflow_info(root: Path, path: Path) -> dict[str, Any]:
    text = read_text(path)
    return {
        "path": str(path.relative_to(root)),
        "has_pull_request": "pull_request" in text,
        "has_push": bool(re.search(r"(?m)^\s*push\s*:", text)),
        "has_schedule": "schedule:" in text or "- cron:" in text,
        "has_workflow_dispatch": "workflow_dispatch" in text,
        "has_paths_filter": "paths:" in text or "paths-ignore:" in text,
        "has_concurrency": "concurrency:" in text,
        "has_permissions": "permissions:" in text,
        "mentions_cache": "cache" in text.lower(),
        "job_count_guess": len(re.findall(r"(?m)^  [A-Za-z0-9_-]+:\s*$", text)),
    }


def discover_workflows(root: Path) -> list[dict[str, Any]]:
    workflows = sorted((root / ".github" / "workflows").glob("*.yml")) + sorted(
        (root / ".github" / "workflows").glob("*.yaml")
    )
    return [workflow_info(root, path) for path in workflows]


def build_recommendations(workflows: list[dict[str, Any]], package: dict[str, Any], root: Path) -> list[str]:
    recommendations: list[str] = []
    scripts = package.get("scripts", {}) if isinstance(package.get("scripts"), dict) else {}
    has_fast_script = any(name in scripts for name in ("test", "lint", "typecheck", "check", "build"))

    if not workflows:
        if has_fast_script:
            recommendations.append(
                "No GitHub Actions workflows detected, but local verification scripts exist. "
                "Consider a lightweight PR workflow if the project is shared or regressions repeat."
            )
        else:
            recommendations.append(
                "No CI workflows or obvious package scripts detected. Start with a local preflight command before adding CI."
            )
    else:
        if not any(item["has_pull_request"] for item in workflows):
            recommendations.append("No pull_request trigger detected; PR regressions may reach review late.")
        if not any(item["has_paths_filter"] for item in workflows):
            recommendations.append("No path filters detected; consider them for expensive checks in larger or private repositories.")
        if not all(item["has_permissions"] for item in workflows):
            recommendations.append("Some workflows lack explicit permissions; consider least-privilege permissions.")
        if not any(item["mentions_cache"] for item in workflows):
            recommendations.append("No dependency cache signal detected; caching may reduce CI time for dependency-heavy projects.")

    package_private = package.get("private")
    if package_private is True:
        recommendations.append(
            "package.json has private=true. Treat CI recommendations as budget-aware unless repository hosting proves it is public."
        )

    if not recommendations:
        recommendations.append("No obvious CI surface issue detected.")
    return recommendations


def main() -> None:
    parser = argparse.ArgumentParser()
    parser.add_argument("--cwd", default=".", help="Repository root to inspect.")
    parser.add_argument("--output", help="Optional JSON output path.")
    args = parser.parse_args()

    root = Path(args.cwd).resolve()
    package = load_package(root)
    workflows = discover_workflows(root)
    scripts = package.get("scripts", {}) if isinstance(package.get("scripts"), dict) else {}
    result = {
        "root": str(root),
        "package_private_flag": package.get("private") if package else None,
        "package_scripts": sorted(scripts.keys()),
        "workflow_count": len(workflows),
        "workflows": workflows,
        "recommendations": build_recommendations(workflows, package, root),
    }
    payload = json.dumps(result, indent=2, sort_keys=True)
    if args.output:
        Path(args.output).write_text(payload + "\n", encoding="utf-8")
    else:
        print(payload)


if __name__ == "__main__":
    main()

#!/usr/bin/env python3
"""Inspect project-level agent guidance files.

This script is intentionally heuristic and dependency-free. It helps an agent
see whether a repository has shared instructions, Claude adapters, symlinks,
imports, and adjacent assistant rule files.
"""

from __future__ import annotations

import argparse
import json
import os
import re
from pathlib import Path
from typing import Any


SKIP_DIRS = {
    ".git",
    "node_modules",
    ".next",
    "dist",
    "build",
    ".venv",
    "venv",
    "__pycache__",
}

GUIDANCE_NAMES = {
    "AGENTS.md",
    "CLAUDE.md",
    ".claude/CLAUDE.md",
    ".github/copilot-instructions.md",
}


def read_text(path: Path, limit: int = 20000) -> str:
    try:
        return path.read_text(encoding="utf-8", errors="replace")[:limit]
    except OSError:
        return ""


def file_info(root: Path, path: Path) -> dict[str, Any]:
    text = read_text(path)
    imports = re.findall(r"(?m)(?:^|\s)@([A-Za-z0-9_./-]+\.md)\b", text)
    return {
        "path": str(path.relative_to(root)),
        "exists": path.exists(),
        "is_symlink": path.is_symlink(),
        "realpath": str(path.resolve()) if path.exists() else None,
        "line_count": text.count("\n") + (1 if text else 0),
        "imports": imports,
        "imports_agents": any(item.endswith("AGENTS.md") for item in imports),
    }


def discover_guidance(root: Path, max_depth: int = 4) -> list[Path]:
    found: list[Path] = []
    for dirpath, dirnames, filenames in os.walk(root):
        rel = Path(dirpath).relative_to(root)
        depth = len(rel.parts)
        dirnames[:] = [d for d in dirnames if d not in SKIP_DIRS and depth < max_depth]
        for filename in filenames:
            candidate = Path(dirpath) / filename
            rel_candidate = candidate.relative_to(root)
            rel_text = str(rel_candidate)
            if rel_text in GUIDANCE_NAMES:
                found.append(candidate)
            elif ".cursor/rules" in rel_text and filename.endswith((".md", ".mdc")):
                found.append(candidate)
            elif ".claude/rules" in rel_text and filename.endswith(".md"):
                found.append(candidate)
    return sorted(set(found))


def build_recommendations(root: Path, infos: list[dict[str, Any]]) -> list[str]:
    by_path = {item["path"]: item for item in infos}
    agents = by_path.get("AGENTS.md")
    claude = by_path.get("CLAUDE.md")
    recommendations: list[str] = []

    if claude and not agents:
        recommendations.append(
            "Portability gap: CLAUDE.md exists but AGENTS.md does not. "
            "Consider creating AGENTS.md as the shared source and converting CLAUDE.md into an adapter."
        )
    if agents and claude:
        same_target = agents.get("realpath") == claude.get("realpath")
        if same_target:
            recommendations.append("AGENTS.md and CLAUDE.md resolve to the same file; edit the shared target once.")
        elif claude.get("imports_agents"):
            recommendations.append("CLAUDE.md imports AGENTS.md; keep shared rules in AGENTS.md and Claude-only notes in CLAUDE.md.")
        else:
            recommendations.append(
                "AGENTS.md and CLAUDE.md are separate with no detected import. "
                "Check for duplicated shared rules and consider linking them."
            )
    if agents and not claude:
        recommendations.append(
            "AGENTS.md exists but CLAUDE.md does not. If Claude Code is used, consider adding a small CLAUDE.md adapter."
        )
    if not agents and not claude:
        recommendations.append(
            "No root AGENTS.md or CLAUDE.md detected. Consider adding shared project instructions if agents work in this repo."
        )

    if not recommendations:
        recommendations.append("No obvious guidance-file issue detected.")
    return recommendations


def main() -> None:
    parser = argparse.ArgumentParser()
    parser.add_argument("--cwd", default=".", help="Repository root to inspect.")
    parser.add_argument("--output", help="Optional JSON output path.")
    args = parser.parse_args()

    root = Path(args.cwd).resolve()
    files = discover_guidance(root)
    infos = [file_info(root, path) for path in files]
    result = {
        "root": str(root),
        "guidance_files": infos,
        "recommendations": build_recommendations(root, infos),
    }

    payload = json.dumps(result, indent=2, sort_keys=True)
    if args.output:
        Path(args.output).write_text(payload + "\n", encoding="utf-8")
    else:
        print(payload)


if __name__ == "__main__":
    main()

